package android.media.audiofx;public class DynamicsProcessing extends AudioEffect {public static int enabledCount,constructionCount,releaseCount,disableCount;public boolean enabled,released,control=true;public OnControlStatusChangeListener listener;public DynamicsProcessing(int p,int session,Object c){if(session<=0)throw new AssertionError("invalid session");constructionCount++;}public boolean hasControl(){return control;}public float gain;public int gainWrites;public void setInputGainAllChannelsTo(float v){gain=v;gainWrites++;}public int setEnabled(boolean b){if(b&&!enabled)enabledCount++;if(!b&&enabled)disableCount++;enabled=b;return SUCCESS;}public boolean getEnabled(){return enabled;}public void release(){releaseCount++;enabled=false;released=true;}public void setControlStatusListener(OnControlStatusChangeListener l){listener=l;}}